export const LEGACY_SHOPPING_LISTS_STORAGE_KEY = "shopping-lists-v1";
export const SHOPPING_LIST_DRAFT_STORAGE_KEY = "shopping-list-draft-v1";
export const EMPTY_SHOPPING_LIST_DRAFT = {
    name: "",
    items: []
};
function isRecord(value) {
    return typeof value === "object" && value !== null;
}
export function isShoppingListItem(value) {
    return isRecord(value)
        && typeof value.id === "string"
        && typeof value.name === "string"
        && typeof value.isCompleted === "boolean";
}
export function isShoppingList(value) {
    return isRecord(value)
        && typeof value.id === "string"
        && typeof value.name === "string"
        && Array.isArray(value.items)
        && value.items.every(isShoppingListItem)
        && typeof value.createdAt === "string"
        && !Number.isNaN(Date.parse(value.createdAt))
        && typeof value.updatedAt === "string"
        && !Number.isNaN(Date.parse(value.updatedAt));
}
function isShoppingListDraft(value) {
    return isRecord(value)
        && typeof value.name === "string"
        && Array.isArray(value.items)
        && value.items.every(isShoppingListItem);
}
export function isShoppingListArray(value) {
    return Array.isArray(value) && value.every(isShoppingList);
}
export function isDeleteShoppingListResponse(value) {
    return isRecord(value) && value.success === true;
}
export function loadShoppingListDraft() {
    let hasError = false;
    try {
        localStorage.removeItem(LEGACY_SHOPPING_LISTS_STORAGE_KEY);
    }
    catch {
        hasError = true;
    }
    try {
        const storedValue = localStorage.getItem(SHOPPING_LIST_DRAFT_STORAGE_KEY);
        if (!storedValue)
            return { data: EMPTY_SHOPPING_LIST_DRAFT, hasError };
        const parsedValue = JSON.parse(storedValue);
        if (!isShoppingListDraft(parsedValue)) {
            return { data: EMPTY_SHOPPING_LIST_DRAFT, hasError: true };
        }
        return { data: parsedValue, hasError };
    }
    catch {
        return { data: EMPTY_SHOPPING_LIST_DRAFT, hasError: true };
    }
}
export function saveShoppingListDraft(draft) {
    try {
        if (!draft.name && draft.items.length === 0) {
            localStorage.removeItem(SHOPPING_LIST_DRAFT_STORAGE_KEY);
            return true;
        }
        localStorage.setItem(SHOPPING_LIST_DRAFT_STORAGE_KEY, JSON.stringify(draft));
        return true;
    }
    catch {
        return false;
    }
}
export function createShoppingListId() {
    if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
        return crypto.randomUUID();
    }
    return `${Date.now()}-${Math.random().toString(36).slice(2)}`;
}
export function orderShoppingListItems(items, orderedIds) {
    if (items.length !== orderedIds.length || new Set(orderedIds).size !== items.length) {
        return items;
    }
    const itemsById = new Map(items.map((item) => [item.id, item]));
    const reorderedItems = [];
    for (const id of orderedIds) {
        const item = itemsById.get(id);
        if (!item)
            return items;
        reorderedItems.push(item);
    }
    return reorderedItems.every((item, index) => item === items[index])
        ? items
        : reorderedItems;
}
export function getShoppingListProgress(items) {
    const total = items.length;
    const completed = items.filter((item) => item.isCompleted).length;
    const percentage = total === 0 ? 0 : Math.round((completed / total) * 100);
    return {
        completed,
        total,
        percentage,
        isCompleted: total > 0 && completed === total
    };
}
export function sortShoppingListsByUpdatedDate(lists) {
    return [...lists].sort((first, second) => (new Date(second.updatedAt).getTime() - new Date(first.updatedAt).getTime()));
}
export function getShoppingListUpdateDateType(date, now = new Date()) {
    const updatedDate = new Date(date);
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const updatedDay = new Date(updatedDate.getFullYear(), updatedDate.getMonth(), updatedDate.getDate());
    const differenceInDays = Math.round((today.getTime() - updatedDay.getTime()) / (24 * 60 * 60 * 1000));
    if (differenceInDays === 0)
        return "today";
    if (differenceInDays === 1)
        return "yesterday";
    return "date";
}
