import { useMutation } from "@tanstack/react-query";
import { createShoppingList, removeShoppingList, updateShoppingList } from "../../api";
export default function useShoppingListsMutations() {
    const createMutation = useMutation({ mutationFn: createShoppingList });
    const updateMutation = useMutation({
        mutationFn: ({ id, data }) => (updateShoppingList(id, data))
    });
    const deleteMutation = useMutation({ mutationFn: removeShoppingList });
    return { createMutation, updateMutation, deleteMutation };
}
