import { AvailableLanguages } from "./types";
export const DEFAULT_LANGUAGE = AvailableLanguages.English;
export const ENABLED_LANGUAGES = [
    AvailableLanguages.English,
    AvailableLanguages.Spanish,
    AvailableLanguages.Russian
];
export const defaultRegionalLocaleByLanguage = {
    [AvailableLanguages.English]: "en-US",
    [AvailableLanguages.Spanish]: "es-ES",
    [AvailableLanguages.Russian]: "ru-RU"
};
export const DEFAULT_REGIONAL_LOCALE = defaultRegionalLocaleByLanguage[DEFAULT_LANGUAGE];
export function getAvailableLanguage(locale) {
    const language = locale.toLowerCase().split("-")[0];
    return ENABLED_LANGUAGES.includes(language) ? language : undefined;
}
export function getRegionalLocale(language, preferredLocales = []) {
    const preferredLocale = preferredLocales.find((locale) => getAvailableLanguage(locale) === language);
    if (!preferredLocale || !preferredLocale.includes("-")) {
        return defaultRegionalLocaleByLanguage[language];
    }
    try {
        return Intl.getCanonicalLocales(preferredLocale)[0];
    }
    catch {
        return defaultRegionalLocaleByLanguage[language];
    }
}
