import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { updateReceiptRequest } from "../../api";
import { useReceiptEditor } from "../../context";
import { getDescriptionKey } from "../../utils/getDescriptionKey";
import { calculateDraftItemTotal, createReceiptDraft, hasValidationErrors, isReceiptDraftDirty, validateReceiptDraft } from "../../utils/receiptForm";
import { createReceiptUpdatePayload } from "../../utils/receiptUpdate";
import useUnsavedReceiptWarning from "../useUnsavedReceiptWarning";
export default function useReceiptEditSession({ descriptions, receipt, setDescriptions, setReceipts }) {
    const { isUpdatingMode, dataForUpdate, setDataForUpdate } = useReceiptEditor();
    const [pristineDraft, setPristineDraft] = useState(null);
    const [isSaving, setIsSaving] = useState(false);
    const [hasSaveError, setHasSaveError] = useState(false);
    const [hasSavedStatus, setHasSavedStatus] = useState(false);
    const headingRef = useRef(null);
    const statusRef = useRef(null);
    const hasMountedRef = useRef(false);
    const validationErrors = useMemo(() => dataForUpdate ? validateReceiptDraft(dataForUpdate) : { fields: {}, items: {} }, [dataForUpdate]);
    const isInvalid = hasValidationErrors(validationErrors);
    const isDirty = Boolean(dataForUpdate && pristineDraft
        && isReceiptDraftDirty(dataForUpdate, pristineDraft));
    const calculatedTotal = useMemo(() => {
        if (dataForUpdate)
            return calculateDraftItemTotal(dataForUpdate.items);
        if (!receipt)
            return 0;
        return receipt.items.reduce((sum, item) => sum + Math.round(item.price * 100), 0) / 100;
    }, [dataForUpdate, receipt]);
    useUnsavedReceiptWarning(isDirty);
    useEffect(() => {
        if (!hasMountedRef.current) {
            hasMountedRef.current = true;
            return;
        }
        headingRef.current?.focus();
    }, [isUpdatingMode]);
    useEffect(() => {
        if (hasSavedStatus)
            statusRef.current?.focus();
    }, [hasSavedStatus]);
    const enterEditMode = useCallback(() => {
        if (!receipt)
            return;
        const draft = createReceiptDraft(receipt, descriptions, getDescriptionKey);
        setHasSavedStatus(false);
        setHasSaveError(false);
        setPristineDraft(draft);
        setDataForUpdate(draft);
    }, [descriptions, receipt, setDataForUpdate]);
    const discardEdit = useCallback(() => {
        setDataForUpdate(undefined);
        setPristineDraft(null);
        setHasSaveError(false);
    }, [setDataForUpdate]);
    const saveReceipt = useCallback(async () => {
        if (!dataForUpdate || isInvalid || isSaving || !isDirty)
            return;
        setIsSaving(true);
        setHasSaveError(false);
        try {
            const payload = createReceiptUpdatePayload(dataForUpdate, descriptions);
            const response = await updateReceiptRequest(payload._id, payload);
            if (!response.ok)
                throw new Error("Failed to update receipt");
            const result = await response.json();
            setReceipts((current) => current.map((item) => (item._id === result.updatedReceipt._id ? result.updatedReceipt : item)));
            if (result.updatedDescriptions && Object.keys(result.updatedDescriptions).length) {
                setDescriptions(result.updatedDescriptions);
            }
            setDataForUpdate(undefined);
            setPristineDraft(null);
            setHasSavedStatus(true);
        }
        catch (error) {
            console.error(error);
            setHasSaveError(true);
        }
        finally {
            setIsSaving(false);
        }
    }, [
        dataForUpdate,
        descriptions,
        isDirty,
        isInvalid,
        isSaving,
        setDataForUpdate,
        setDescriptions,
        setReceipts
    ]);
    return {
        calculatedTotal,
        discardEdit,
        enterEditMode,
        hasSaveError,
        hasSavedStatus,
        headingRef,
        isDirty,
        isInvalid,
        isSaving,
        isUpdatingMode,
        saveReceipt,
        statusRef,
        validationErrors
    };
}
