import { getDescriptionKey } from "./getDescriptionKey";
import { serializeReceiptDraft } from "./receiptForm";
export function createReceiptUpdatePayload(draft, descriptions) {
    const receipt = serializeReceiptDraft(draft);
    return {
        ...receipt,
        items: receipt.items.map((item) => (descriptions[getDescriptionKey(item.name)] === item.description
            ? { ...item, description: undefined }
            : item))
    };
}
