import { useCallback } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { SHOPPING_LISTS_QUERY_KEY } from "../../constants";
export default function useShoppingListsCache() {
    const queryClient = useQueryClient();
    const getList = useCallback((id) => (queryClient.getQueryData(SHOPPING_LISTS_QUERY_KEY)
        ?.find((list) => list.id === id)), [queryClient]);
    const replaceList = useCallback((shoppingList) => {
        queryClient.setQueryData(SHOPPING_LISTS_QUERY_KEY, (current = []) => (current.some((item) => item.id === shoppingList.id)
            ? current.map((item) => item.id === shoppingList.id ? shoppingList : item)
            : [shoppingList, ...current]));
    }, [queryClient]);
    const removeList = useCallback((id) => {
        queryClient.setQueryData(SHOPPING_LISTS_QUERY_KEY, (current = []) => (current.filter((list) => list.id !== id)));
    }, [queryClient]);
    return { getList, replaceList, removeList };
}
