import { useQuery } from "@tanstack/react-query";
import { loadShoppingLists } from "../../api";
import { SHOPPING_LISTS_QUERY_KEY } from "../../constants";
export default function useShoppingListsQuery(enabled = true) {
    return useQuery({
        enabled,
        queryKey: SHOPPING_LISTS_QUERY_KEY,
        queryFn: ({ signal }) => loadShoppingLists(signal)
    });
}
