import { useCallback, useEffect, useState } from "react";
import { useFilters } from "../../../filters";
import { getEarliestReceiptRequest, getReceiptDescriptionsRequest } from "../../api";
import loadReceipts from "../../api/loadReceipts";
export default function useReceiptsController() {
    const [receipts, setReceipts] = useState([]);
    const [earliestReceipt, setEarliestReceipt] = useState(null);
    const [latestReceipt, setLatestReceipt] = useState(null);
    const [descriptions, setDescriptions] = useState({});
    const [isLoading, setIsLoading] = useState(true);
    const [hasError, setHasError] = useState(false);
    const [retryKey, setRetryKey] = useState(0);
    const { startDate, endDate } = useFilters();
    const retry = useCallback(() => setRetryKey((key) => key + 1), []);
    useEffect(() => {
        let ignore = false;
        async function loadMetadata() {
            try {
                const [rangeResponse, descriptionsResponse] = await Promise.all([
                    getEarliestReceiptRequest(),
                    getReceiptDescriptionsRequest()
                ]);
                if (!rangeResponse.ok || !descriptionsResponse.ok) {
                    throw new Error("Failed to load receipt metadata");
                }
                const range = await rangeResponse.json();
                const receiptDescriptions = await descriptionsResponse.json();
                if (!ignore) {
                    setEarliestReceipt(range.earliest || null);
                    setLatestReceipt(range.latest || null);
                    setDescriptions(receiptDescriptions.descriptions || {});
                }
            }
            catch (loadError) {
                if (!ignore)
                    console.error(loadError);
            }
        }
        loadMetadata();
        return () => { ignore = true; };
    }, [retryKey]);
    useEffect(() => {
        if (!startDate || !endDate || startDate > endDate)
            return;
        let ignore = false;
        setIsLoading(true);
        setHasError(false);
        async function loadData() {
            try {
                const loadedReceipts = await loadReceipts({ startDate, endDate });
                if (!ignore)
                    setReceipts(loadedReceipts);
            }
            catch (loadError) {
                if (!ignore) {
                    console.error(loadError);
                    setHasError(true);
                    setReceipts([]);
                }
            }
            finally {
                if (!ignore)
                    setIsLoading(false);
            }
        }
        loadData();
        return () => { ignore = true; };
    }, [startDate, endDate, retryKey]);
    return {
        receipts,
        earliestReceipt,
        latestReceipt,
        descriptions,
        isLoading,
        hasError,
        retry,
        setReceipts,
        setDescriptions
    };
}
